#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: fleet #152 (spec fleet #93, ADR 0015). The fleet's machine user:
# account, token, collaborator rights, the secret gh config directory, and the
# checks that prove each. Run from Git Bash in CORY's shell, never inside a
# fleet session. Re-runnable: the login is remembered, the token is not (the
# token only ever lands in the gh config directory, via gh itself).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
FLEET_HOME="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPOS=(andydarknessb/Endzone-Empire andydarknessb/Nidus andydarknessb/fleet)
SCOPES_WANTED=(repo workflow read:org)
_win() { if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else printf '%s' "$1"; fi; }
_unix() { if command -v cygpath >/dev/null 2>&1; then cygpath -u "$1"; else printf '%s' "$1"; fi; }
if [[ -n "${FLEET_IDENTITY_DIR:-}" ]]; then IDENTITY_DIR_WIN="$FLEET_IDENTITY_DIR"; else IDENTITY_DIR_WIN="$(_win "${USERPROFILE:-$HOME}")\\.fleet-identity\\gh"; fi
IDENTITY_DIR="$(_unix "$IDENTITY_DIR_WIN")"
# The login (not a secret) is remembered beside, not inside, the gh config directory.
ENV_FILE="$(dirname "$IDENTITY_DIR")/wizard.env"
mkdir -p "$(dirname "$IDENTITY_DIR")"

# as_cory CMD... / as_fleet CMD...: the same gh, under each login.
as_cory()  { env -u GH_CONFIG_DIR -u GH_TOKEN -u GITHUB_TOKEN -u GIT_CONFIG_SYSTEM "$@"; }
as_fleet() { env -u GH_TOKEN -u GITHUB_TOKEN GH_CONFIG_DIR="$IDENTITY_DIR_WIN" GH_PROMPT_DISABLED=1 "$@"; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
FAILED=()
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; FAILED+=("$1"); }

if [[ -n "${GH_CONFIG_DIR:-}" || -n "${FLEET_NAME:-}" ]]; then
  printf '%sThis shell is a fleet session (GH_CONFIG_DIR or FLEET_NAME is set). Run the wizard from your own terminal.%s\n' "$RED" "$RESET"
  exit 1
fi
command -v gh >/dev/null 2>&1 || { printf 'gh is not on PATH\n'; exit 1; }
CORY_LOGIN="$(as_cory gh api user --jq .login 2>/dev/null || true)"
[[ -n "$CORY_LOGIN" ]] || { printf 'gh in this shell is not logged in (run gh auth status)\n'; exit 1; }

banner "Fleet identity: the fleet's own GitHub login (fleet #152, ADR 0015)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the machine user account"
say "The fleet needs its own GitHub account. Sign up in a PRIVATE browser window,"
say "so your own session stays signed in as ${CORY_LOGIN}."
step "Use an email you control that is not already on GitHub (a Gmail plus address works: you+fleet@gmail.com)."
step "Pick a login you will recognise in PR lists, e.g. ${CORY_LOGIN}-fleet or endzone-fleet."
step "Turn on two-factor authentication for it (Settings, Password and authentication)."
open_url "https://github.com/signup"
pause "Press Enter once the account exists and you are signed in to it in the private window"
while :; do
  ask FLEET_LOGIN "The machine user's login:"
  if [[ -z "$FLEET_LOGIN" ]]; then warn "a login is required"; continue; fi
  if [[ "${FLEET_LOGIN,,}" == "${CORY_LOGIN,,}" ]]; then warn "that is your own login; the whole point is a second one"; continue; fi
  if as_cory gh api "users/$FLEET_LOGIN" --jq .login >/dev/null 2>&1; then ok "github.com/$FLEET_LOGIN exists"; break; fi
  warn "github.com/$FLEET_LOGIN was not found; check the spelling"
done
write_env FLEET_LOGIN "$FLEET_LOGIN"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Mint the token (signed in as ${FLEET_LOGIN})"
say "A CLASSIC token: a fine-grained one cannot reach repos owned by your personal account."
step "In the private window (signed in as ${FLEET_LOGIN}), the page below opens with the scopes pre-ticked."
step "Note: fleet-identity. Expiration: 1 year (rotating = re-running this wizard)."
step "Scopes: repo, workflow, read:org and NOTHING else (no admin:*, no delete_repo)."
step "Generate, then copy the token (it starts with ghp_)."
open_url "https://github.com/settings/tokens/new?description=fleet-identity&scopes=repo,workflow,read:org"
FLEET_TOKEN=""
while [[ -z "$FLEET_TOKEN" ]]; do
  printf '  %sPaste the token (hidden):%s ' "$BOLD" "$RESET"; read -rs FLEET_TOKEN || true; printf '\n'
  if [[ "$FLEET_TOKEN" == github_pat_* ]]; then warn "that is a fine-grained token; mint a classic one (tokens/new)"; FLEET_TOKEN=""; continue; fi
  if [[ "$FLEET_TOKEN" != ghp_* ]]; then warn "that does not look like a classic token"; FLEET_TOKEN=""; fi
done

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Store the token in the fleet's gh config directory"
say "Target: ${IDENTITY_DIR_WIN}"
note "gh writes it to hosts.yml there (--insecure-storage), NOT to your keyring."
mkdir -p "$IDENTITY_DIR"
if printf '%s' "$FLEET_TOKEN" | as_fleet gh auth login --hostname github.com --git-protocol https --insecure-storage --with-token; then
  ok "gh auth login wrote ${IDENTITY_DIR_WIN}\\hosts.yml"
else
  fail "gh auth login refused the token (see above); re-run the wizard"
fi
unset FLEET_TOKEN
# Only your account (the one the scheduled tasks run as) can read the directory.
if command -v icacls >/dev/null 2>&1; then
  if MSYS_NO_PATHCONV=1 icacls "$IDENTITY_DIR_WIN" /inheritance:r /grant:r "${USERNAME}:(OI)(CI)F" >/dev/null 2>&1; then
    ok "ACL: only ${USERNAME} can read ${IDENTITY_DIR_WIN}"
  else
    warn "could not tighten the ACL with icacls"; SKIPPED+=("tighten the ACL on ${IDENTITY_DIR_WIN} to your user only")
  fi
fi
# Your keyring must be untouched: your own gh still answers as you.
AFTER="$(as_cory gh api user --jq .login 2>/dev/null || true)"
if [[ "$AFTER" == "$CORY_LOGIN" ]]; then ok "your own shell still acts as ${CORY_LOGIN}"; else fail "your shell now answers as '${AFTER}', not ${CORY_LOGIN}"; fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Invite ${FLEET_LOGIN} to the three repos, and accept as ${FLEET_LOGIN}"
note "Invites are sent as ${CORY_LOGIN}; they are accepted with the fleet's own token. No browser needed."
for repo in "${REPOS[@]}"; do
  if as_cory gh api -X PUT "repos/$repo/collaborators/$FLEET_LOGIN" -f permission=push >/dev/null 2>&1; then ok "invited to $repo (write)"; else fail "could not invite ${FLEET_LOGIN} to $repo"; fi
done
INVITES="$(as_fleet gh api user/repository_invitations --jq '.[] | "\(.id) \(.repository.full_name)"' 2>/dev/null || true)"
while read -r id full; do
  [[ -n "$id" ]] || continue
  for repo in "${REPOS[@]}"; do
    if [[ "${full,,}" == "${repo,,}" ]]; then
      if as_fleet gh api -X PATCH "user/repository_invitations/$id" >/dev/null 2>&1; then ok "accepted $full"; else fail "could not accept the invitation to $full"; fi
    fi
  done
done <<< "$INVITES"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Verify: login, scopes, write-not-admin, no ruleset bypass"
FLEET_SEEN="$(as_fleet gh api user --jq .login 2>/dev/null || true)"
if [[ "${FLEET_SEEN,,}" == "${FLEET_LOGIN,,}" ]]; then ok "the stored token is ${FLEET_SEEN}"; else fail "the stored token answers as '${FLEET_SEEN}', expected ${FLEET_LOGIN}"; fi
FLEET_ID="$(as_fleet gh api user --jq .id 2>/dev/null || true)"
SCOPES="$(as_fleet gh api -i user 2>/dev/null | tr -d '\r' | sed -n 's/^[Xx]-[Oo][Aa]uth-[Ss]copes: //p')"
SCOPES="${SCOPES// /}"
for s in "${SCOPES_WANTED[@]}"; do
  if [[ ",${SCOPES}," == *",$s,"* ]]; then ok "scope $s"; else fail "token lacks scope $s (has: ${SCOPES})"; fi
done
for s in ${SCOPES//,/ }; do
  keep=0; for w in "${SCOPES_WANTED[@]}"; do [[ "$s" == "$w" ]] && keep=1; done
  (( keep )) || fail "token carries an extra scope '$s'; ADR 0015 allows only ${SCOPES_WANTED[*]}"
done
for repo in "${REPOS[@]}"; do
  perm="$(as_fleet gh api "repos/$repo/collaborators/$FLEET_LOGIN/permission" --jq .permission 2>/dev/null || true)"
  [[ -n "$perm" ]] || perm="$(as_cory gh api "repos/$repo/collaborators/$FLEET_LOGIN/permission" --jq .permission 2>/dev/null || true)"
  if [[ "$perm" == "write" ]]; then ok "$repo: permission write"; else fail "$repo: permission is '${perm:-none}', expected write (not admin)"; fi
  # Bypass actors are visible to admins only, so the rulesets are read as you.
  for rs in $(as_cory gh api "repos/$repo/rulesets" --jq '.[].id' 2>/dev/null || true); do
    hit="$(as_cory gh api "repos/$repo/rulesets/$rs" --jq "[.bypass_actors[]? | select(.actor_type == \"User\" and ((.actor_id|tostring) == \"$FLEET_ID\"))] | length" 2>/dev/null || echo 0)"
    name="$(as_cory gh api "repos/$repo/rulesets/$rs" --jq .name 2>/dev/null || echo "$rs")"
    if [[ "$hit" == "0" ]]; then ok "$repo ruleset '$name': ${FLEET_LOGIN} is not a bypass actor"; else fail "$repo ruleset '$name' lists ${FLEET_LOGIN} as a bypass actor"; fi
  done
done
PLAN="$(node "$(_win "$FLEET_HOME")\\bin\\identity.js" plan --root "$(_win "$FLEET_HOME")" 2>&1 | tail -n1 || true)"
if [[ "$PLAN" == *'"present":true'* ]]; then ok "bin/identity.js plan sees the directory as ${FLEET_LOGIN}"; else fail "bin/identity.js plan: $PLAN"; fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Prove the pusher (optional): push a probe branch as the fleet"
say "Pushes an existing commit to a throwaway branch with the SAME environment a fleet"
say "session gets, reads GitHub's events API for the pusher, then deletes the branch."
note "The events API can lag a few minutes; a timeout here is not a failure of the token."
probe() {
  local repo="$1" checkout="$2" ref="$3" branch sha actor=""
  branch="identity-probe/$(date -u +%Y%m%d%H%M%S)"
  sha="$(git -C "$checkout" rev-parse "$ref" 2>/dev/null)" || { SKIPPED+=("probe $repo: $ref not found in $checkout"); return; }
  local envs=(GH_CONFIG_DIR="$IDENTITY_DIR_WIN" GIT_CONFIG_SYSTEM="${IDENTITY_DIR_WIN}\\gitconfig" GIT_TERMINAL_PROMPT=0 GH_PROMPT_DISABLED=1)
  if ! env -u GH_TOKEN "${envs[@]}" git -C "$checkout" push -q "https://github.com/$repo.git" "$sha:refs/heads/$branch"; then fail "probe push to $repo failed"; return; fi
  for _ in $(seq 1 12); do
    actor="$(as_cory gh api "repos/$repo/events?per_page=30" --jq ".[] | select(.type==\"PushEvent\" and .payload.ref==\"refs/heads/$branch\") | .actor.login" 2>/dev/null | head -n1)"
    [[ -n "$actor" ]] && break
    sleep 10
  done
  env -u GH_TOKEN "${envs[@]}" git -C "$checkout" push -q "https://github.com/$repo.git" ":refs/heads/$branch" || SKIPPED+=("delete probe branch $branch on $repo")
  if [[ -z "$actor" ]]; then
    SKIPPED+=("pusher on $repo not visible in the events API within 2 min; check https://github.com/$repo/activity"); warn "$repo: pusher not visible yet"
  elif [[ "${actor,,}" == "${FLEET_LOGIN,,}" ]]; then ok "$repo: pushed by ${actor}"
  else fail "$repo: pushed by ${actor}, not ${FLEET_LOGIN}"; fi
}
if confirm "Probe the fleet repo (andydarknessb/fleet)?"; then probe andydarknessb/fleet "$FLEET_HOME" origin/master; fi
ENDZONE_CHECKOUT="${ENDZONE_CHECKOUT:-/e/Endzone-Empire}"
if [[ -e "$ENDZONE_CHECKOUT/.git" ]] && confirm "Probe the tenant repo (andydarknessb/Endzone-Empire, from $ENDZONE_CHECKOUT)?"; then
  git -C "$ENDZONE_CHECKOUT" fetch -q origin integration 2>/dev/null || true
  probe andydarknessb/Endzone-Empire "$ENDZONE_CHECKOUT" origin/integration
fi

finish
if (( ${#FAILED[@]} )); then
  warn "checks that failed:"; for f in "${FAILED[@]}"; do note "  - $f"; done
  printf '\n'; exit 1
fi
say "Next: fleet #154 sets fleetIdentity to ${FLEET_LOGIN} in tenants/endzone.json and tenants/nidus.json."
say "Until then fleet sessions already act as ${FLEET_LOGIN} and the premise check reads expected-until-154."
